result.output:
{
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixpkgs-unstable";
    home-manager = {
      url = "github:nix-community/home-manager";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    nix-darwin = {
      url = "github:LnL7/nix-darwin";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    sops-nix = {
      url = "github:Mic92/sops-nix";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    walker.url = "github:abenz1267/walker";
    nixgl.url = "github:guibou/nixGL";
    # Follow our nixpkgs: nixGL pins its own, whose mesa (25.0) predates
    # Panther Lake / Xe3 and deadlocked Hyprland on shiori at startup.
    nixgl.inputs.nixpkgs.follows = "nixpkgs";
    explore-mcp.url = "github:sauyon/explore-mcp";
    explore-mcp.inputs.nixpkgs.follows = "nixpkgs";
    # drovr — CLI for single-writer/compressed-handoff agent phases; ships the
    # `drovr` binary plus drovr:* Claude skills under share/drovr/.
    drovr.url = "git+https://forge.ko.ag/drovr/drovr.git";
    drovr.inputs.nixpkgs.follows = "nixpkgs";
    # Terminal diff viewer for agent changesets; ships a `hunk-review` Claude
    # skill under `${hunk}/skills/`.
    hunk.url = "github:modem-dev/hunk";
    # Matt Pocock's agent skills. Not a flake — a plain tree of SKILL.md
    # bundles under skills/<category>/<name>/, consumed by path below.
    mattpocock-skills.url = "github:mattpocock/skills";
    mattpocock-skills.flake = false;
    # Seamless OIDC SSH gate (gate binary + nixos/darwin modules).
    ssh-oidc.url = "git+https://codeberg.org/sauyon/ssh-oidc";
  };

  outputs = { nixpkgs, home-manager, nix-darwin, sops-nix, walker, nixgl, explore-mcp, drovr, hunk, mattpocock-skills, ssh-oidc, ... }:
  let
    mkHome = system: machine: home-manager.lib.homeManagerConfiguration {
      pkgs = nixpkgs.legacyPackages.${system};
      extraSpecialArgs = {
        inherit sops-nix walker nixgl explore-mcp drovr hunk mattpocock-skills machine;
        inherit system;
      };
      modules = [ ./home.nix ];
    };
    linuxHome = mkHome "x86_64-linux";
  in {
    homeConfigurations.utsuho = linuxHome {
      hostname = "utsuho";
      gui = true;
      gpu = "amd";
    };
    homeConfigurations.kyuusaku = linuxHome {
      hostname = "kyuusaku";
      gui = false;
      homeDir = "/local/mnt/workspace/kyuusaku";
    };
    homeConfigurations.setsuna = linuxHome {
----
    homeConfigurations.setsuna = linuxHome {
      hostname = "setsuna";
      gui = true;
    };
    homeConfigurations.shiori = linuxHome {
      hostname = "shiori";
      gui = true;
    };
    homeConfigurations.fujiwara = linuxHome {
      hostname = "fujiwara";
      # Headless: the box has an HDMI display wired up, but no graphical session
      # has run on it since Jun 2025. Dropping the desktop stack (hyprland,
      # waybar, walker, kanshi, portals) rather than leaving units to fail at
      # every activation. Flip back to true if it becomes a workstation again.
      gui = false;
      gpu = "amd";
    };
    homeConfigurations.mari = mkHome "aarch64-darwin" {
      hostname = "mari";
      gui = true;
    };

    darwinConfigurations.mari = nix-darwin.lib.darwinSystem {
      system = "aarch64-darwin";
      modules = [
        sops-nix.darwinModules.sops
        ssh-oidc.darwinModules.default
        ({ config, ... }: {
          programs.zsh.enable = true;
          nix.enable = true;
          nix.settings.experimental-features = [ "nix-command" "flakes" ];

          # Self-hosted attic binary cache (kube cluster); signing key is public.
          # Assumes nix-darwin manages nix (nix.enable = true). If mari moves to
          # Determinate Nix, relocate this to /etc/determinate like the Linux boxes.
          nix.settings.extra-substituters = [ "https://attic.ko.ag/kube" ];
          nix.settings.extra-trusted-public-keys = [ "kube:REDACTED" ];
          # Private cache → read token via netrc, rendered as root by sops-nix.
          sops.secrets.atticPullToken = { };
          sops.templates."attic-netrc".content = "machine attic.ko.ag password ${config.sops.placeholder.atticPullToken}";
          nix.settings.netrc-file = config.sops.templates."attic-netrc".path;

          # Remote builder: Linux boxes delegate aarch64-darwin builds here over
          # Tailscale. The gate's ForceCommand would hijack the non-interactive
          # `nix-store --serve` path if it shared the human `sauyon` login, so the
          # builder connects as the dedicated `nixremote` user, carved out by the
          # ssh-oidc-gate Match block below. Both users must be nix trusted-users.
          # DEPLOY: update the Linux boxes' nix.custom.conf `builders` line from
          #   ssh-ng://sauyon@100.106.204.103 ...   to   ssh-ng://nixremote@100.106.204.103 ...
          # and ensure the builder pubkey is in /run/secrets/ssh-oidc-builder-key.pub here.
          nix.settings.trusted-users = [ "sauyon" "nixremote" ];
          system.stateVersion = 6;
          nixpkgs.hostPlatform = "aarch64-darwin";

          environment.etc."sops/age-unused.txt".text = "";
          sops.defaultSopsFile = ./secrets.yaml;
          sops.age.keyFile = "/etc/sops/age-unused.txt";
          sops.age.sshKeyPaths = [ ];
          sops.gnupg.sshKeyPaths = [ ];
          sops.environment.GOOGLE_APPLICATION_CREDENTIALS = "/Users/sauyon/.config/sops/gcp-key.json";
          # Human key(s). With the OIDC gate active, its always-accept
          # AuthorizedKeysCommand (not this file) decides the publickey stage for
          # the `sauyon` login; the builder carve-out is handled separately
          # (sshOidcBuilderKey, below).
          sops.secrets."ssh-authorized-keys-sauyon" = {
            mode = "0644";
          };

          # ssh-oidc gate. Shared bearer token for the enrollment service;
          # rendered by sops-nix, read by the gate at runtime (never in the store).
          # NOTE: add an `sshOidcToken` key to secrets.yaml (the gate's service token).
          sops.secrets.sshOidcToken = {
            # Readable by the login (sauyon) user — the gate runs as that user.
            mode = "0444";
          };
          # The remote-builder's PUBLIC key, in its own authorized_keys file, used by
          # the gate's Match-block carve-out for the `nixremote` builder user.
          # NOTE: add an `sshOidcBuilderKey` key to secrets.yaml (the builder pubkey,
          # the same value currently in `mariBuilderKey`'s public half).
          sops.secrets.sshOidcBuilderKey = {
            mode = "0444";

    #custom-caffeine.off { color: @comment; }
    #custom-caffeine.on { color: @yellow; }

    #wireplumber { color: @cyan; }
    #wireplumber.muted { color: @comment; }
    #network { color: @green; }
    #network.disconnected { color: @red; }
    #bluetooth { color: @blue; }
    #bluetooth.disabled, #bluetooth.off { color: @comment; }
    #memory { color: @orange; }
    #battery { color: @green; }
    #battery.warning:not(.charging) { color: @yellow; }
    #battery.critical:not(.charging) { color: @red; }
    #battery.charging { color: @cyan; }
    #clock { color: @fg; font-weight: 600; }
    #custom-notifications { color: @yellow; }
    #custom-notifications.dnd { color: @comment; }

    tooltip {
      background: @bg-darker;
      border: 1px solid @border;
    }
    tooltip label { color: @fg; padding: 6px; }
  '';
};

thunderbird = lib.optionalAttrs (!isDarwin && isDesktop) {
  enable = true;
  profiles.default = {
    isDefault = true;
    extensions = [
      (pkgs.fetchFirefoxAddon {
        name = "tbkeys";
        url = "https://github.com/wshanks/tbkeys/releases/download/v2.4.3/tbkeys.xpi";
        hash = "REDACTED";
      })
    ];
  };
  settings = {
    "mail.tabs.drawInTitlebar" = false;
    "ui.key.accelKey" = 91;
    "ui.key.textcontrol.prefer_native_key_bindings_over_builtin_shortcut_key_definitions" = true;
    "extensions.tbkeys.mainkeys" = builtins.toJSON {
      # cycle panes
      "ctrl+x o" = "eval:document.commandDispatcher.advanceFocus()";
      # navigation
      "alt+n" = "cmd:cmd_nextMsg";
      "alt+p" = "cmd:cmd_previousMsg";
      # actions
      "c" = "cmd:cmd_newMessage";
      "r" = "cmd:cmd_reply";
      "a" = "cmd:cmd_replyAll";
      "f" = "cmd:cmd_forward";
      "d" = "cmd:cmd_delete";
      "e" = "cmd:cmd_archive";
      "enter" = "cmd:cmd_openMessage";
      "u" = "tbkeys:closeMessageAndRefresh";
      # unset defaults that conflict
      "j" = "unset";
      "k" = "unset";
      "o" = "unset";
      "x" = "unset";
      "#" = "unset";
    };
  };
};

claude-code = {
  enable = true;
  # enableMcpIntegration = true;
  # ~/.claude/settings.json is the unprofiled fallback (used by `command
  # claude` and any non-claude-prof invoker). It uses the work profile's
  # settings so behavior matches `claude-prof run work`. Per-profile
  # settings.json lives under ~/.config/claude-<name>/ (rendered by home.file
  # below).
  settings = claudeProfileSettings.work;
  # No version/src override: nixpkgs now leads upstream's native-binary
  # releases, and its installPhase unzstds a `claude.zst` src that the old
  # uncompressed-binary pin could not satisfy.
};

home-manager.enable = true;

difftastic = {
  enable = !isDarwin;
  # Deliberately NOT wiring git integration: `git.enable = true` sets
  # `diff.external`, making `git diff` emit difftastic's structural view
  # instead of a unified diff. That breaks the pager (diff-so-fancy can't
  # parse it), `git diff > x.patch`, and every tool/skill that parses diff
  # output. `git dft` (alias below) opts in per-invocation instead.
  git.enable = false;
  options = {
    # display = "inline";
  };
};
firefox = {
  enable = isDesktop;
  # Linux: env.nix sets MOZ_LEGACY_PROFILES=1 (and system Arch firefox uses
  # legacy unconditionally), so use .mozilla/firefox. macOS reads from
  # ~/Library/Application Support/Firefox.
  configPath = if isDarwin then "Library/Application Support/Firefox" else ".mozilla/firefox";
  # Drop Version= so Firefox uses non-dedicated profile mode and honors
  # Default=1 — else Firefox 67+ pins profile-per-install via [Install<HASH>]
  # sections in profiles.ini and ignores Default=.
  profileVersion = null;
  policies = {
    Homepage = {
      URL = "https://ko.ag/newtab.html";
      StartPage = "homepage";
    };
  };
  nativeMessagingHosts = lib.optionals (!isDarwin) [
    pkgs.tridactyl-native
  ];
  profiles.default = {
    extensions.packages = lib.optionals (!isDarwin) (with pkgs.nur.repos.rycee.firefox-addons; [
      bitwarden
      tridactyl
    ]);
    settings = {
      "sidebar.verticalTabs" = true;
      "ui.key.accelKey" = 91;
      "ui.key.textcontrol.prefer_native_key_bindings_over_builtin_shortcut_key_definitions" = true;
      "signon.rememberSignons" = false;
      "browser.newtab.extensionControlled" = false;
      "browser.ml.chat.enabled" = false;
      # WebTransport workaround: this profile reports hasThirdPartyRoots=1
      # for every QUIC connection (even public sites chaining to built-in
      # roots), so Firefox's third-party-roots policy kills H3. HTTPS falls
      # back to H2; WebTransport has no fallback and fails with "WebTransport
      # connection rejected". See netwerk/protocol/http/Http3Session.cpp
      # Authenticated() and bugzilla 1929093.
      "network.http.http3.disable_when_third_party_roots_found" = false;
    };
  };
};
ghostty = lib.mkIf (!isDarwin) {
  enable = isDesktop;
  package = config.lib.nixGL.wrap pkgs.ghostty;
  enableZshIntegration = true;
  systemd.enable = false;
  # installBatSyntax = true;

  settings = {
    # Anything but `epoll`, which this was from 2026-08-28 to 2026-09-26
    # and which segfaults ghostty outright. Pinned rather than left at the
    # default `auto` to state the intent: never epoll by choice. Note that
    # neither spelling is a guarantee -- ghostty falls back to another
    # backend when the requested one is unavailable, and on Linux the only
    # other backend IS epoll, so a host with io_uring disabled (hardened
    # kernel, `kernel.io_uring_disabled=1|2`, a restricted container) lands
    # back on the crashing path with no signal. shiori reads 0 today; the
    # other hosts sharing this file were not checked.
    #
    # Untested in the direction that matters: the crash below has not been
    # observed even once under io_uring, because it was never reproduced on
    # demand at all. The mechanism says io_uring cannot reach this path --
    # it is epoll-backend-only -- but the diagnosis rests on the crash
    # signature, not on a reproduction, so this is a move away from a
    # known-bad backend rather than a verified fix.
    #
    # libxev's epoll backend runs a completion's callback for every epoll
    # event it receives without checking the completion is still
    # outstanding. When stream.WriteQueue has drained q_inner on an earlier
    # event in the same batch, a later callback finds q_inner.head == null
    # and the `.?` unwrap in ReleaseFast yields NULL, which is then
    # dereferenced at field offset 0x108. That kills ghostty's `io` thread,
    # so the whole process dies and every window goes with it.
    #
    # Any burst of reply-generating queries can hit it. `herdr` attaching
    # sends 258 of them in its first frame -- OSC 10/11 plus OSC 4;0..255 --
    # and took ghostty 1.3.1 down 3/3 times on 2026-09-26, each crash 30ms,
    # 5ms and 4ms after the client handshake in herdr-server.log -- the
    # preamble's own replies, nothing later. (`journalctl -k -o
    # short-precise` against the connect lines; the herdr-side detach is
    # 0.5-0.8s behind, but that is the server noticing the socket close.)
    # Each a null
    # deref at 0x108 in a thread named `io`. Same signature, same code
    # offset, all three. The race is batch-timing dependent, so it does not
    # reproduce on demand (0 hits in 24 local runs of the upstream flood).
    #
    # mitchellh/libxev#239 is the fix and is unmerged, so no ghostty release
    # carries it yet. Re-test `epoll` once it lands; see also
    # omacom/omarchy#12917, which names herdr as the trigger.
    #
    # Why epoll was tempting, and what io_uring costs: ghostty's libxev loop
    # parks one thread per ring in io_cqring_wait(), which sleeps via
    # io_schedule() and so sets current->in_iowait. The kernel counts that
    # as blocked-on-IO -- it lands in procs_blocked and is flagged
    # TSK_IOWAIT for PSI -- even though the ring only holds idle
    # IORING_OP_POLL_ADD watches on the pty fds and no disk IO happens.
    #
    # Because every other thread in the cgroup is idle-sleeping, PSI's
    # "full" (all non-idle tasks stalled) reads ~100% for ghostty's scope
    # and sums up the cgroup chain into user.slice and /proc/pressure/io.
    # Measured 2026-08-28: fujiwara's session scope sat at full avg300=99.88
    # for its entire 88-day life with every disk at inflight=0; utsuho had
    # 4 rings, 4 threads in io_cqring_wait and procs_blocked exactly 4,
    # while Slack and Firefox read 0.00 (they use epoll).
    #
    # This is ghostty-org/ghostty#3246 / discussion#3224, whose accepted
    # answer was exactly the epoll setting. Kernel commit 7b72d661f1f2 (6.5)
    # gated iowait on having pending requests, which does NOT help here: the
    # armed pty polls *are* pending requests. The real upstream fix is
    # IORING_ENTER_NO_IOWAIT (kernel 6.15+, probed via IORING_FEAT_NO_IOWAIT),
    # which Zig's IoUring does not expose yet -- ziglang/zig#25566.
    #
    # So the accounting noise stays until libxev passes NO_IOWAIT. It is
    # cosmetic; the epoll crash was not.
    async-backend = "io_uring";

  CARGO_HOME = "${xdg.dataHome}/cargo";
  RUSTUP_HOME = "${xdg.dataHome}/rustup";
  ASPELL_CONF = "per-conf ${xdg.configHome}/aspell/aspell.conf; personal ${xdg.configHome}/aspell/en.personal; repl ${xdg.configHome}/aspell/en.prepl";
  ZSH_CACHE_DIR = "${xdg.cacheHome}/zsh";

  GOPATH = "${home}/devel/go";

  # Prepend the home-manager profile bin so it lands in environment.d too. Login
  # shells get it from hm-session-vars.sh, but the systemd user manager (and thus
  # services like walker that spawn `firefox` by name) only sees this PATH; its
  # PAM-inherited $PATH is just /usr/local/bin:/usr/bin.
  PATH = "${home}/.nix-profile/bin:$PATH:/snap/bin:$GOPATH/bin:${xdg.dataHome}/cargo/bin:${home}/.local/bin:${home}/.krew/bin";

  GRAVEYARD = "$XDG_RUNTIME_DIR/trash";

  PAGER = "${pkgs.bat}/bin/bat --paging=always --color=always --decorations=never --";
  BAT_PAGER = "${pkgs.less}/bin/less";
  LESS = "-RFx4";

  # gpg for ssh
  GPG_TTY = "$(tty)";

  "_JAVA_AWT_WM_NONREPARENTING" = "1";

  QT_QPA_PLATFORM = "wayland";
  QT_WAYLAND_DISABLE_WINDOWDECORATION = "1";

  MOZ_ENABLE_WAYLAND = "1";
  MOZ_LEGACY_PROFILES = "1";

  WARP_ENABLE_WAYLAND = "1";

  TG_PROVIDER_CACHE = "1";

  # cursor-agent otherwise dumps verbose debug logs to
  # $TMPDIR/cursor-agent-logs-<uid>; $TMPDIR is /tmp (tmpfs, i.e. RAM). These
  # grow unbounded (observed 11G) and get paged to swap. Disable them.
  CURSOR_AGENT_DISABLE_DEBUG_LOG = "1";

  # `coder config-ssh` (run by IDE integrations / `coder` tooling) rewrites its
  # target SSH config in place, dereferencing and clobbering the read-only store
  # symlink home-manager puts at ~/.ssh/config. Redirect those writes to a
  # throwaway file nothing Includes; the nix-managed *.coder blocks in home.nix's
  # programs.ssh.settings are the real source of truth.
  CODER_SSH_CONFIG_FILE = "${xdg.configHome}/coderv2/ssh-config";
}
// lib.optionalAttrs (!pkgs.stdenv.hostPlatform.isDarwin) {
  SSH_AGENT_PID = "";
  # ssh-tpm-agent is the primary SSH agent (programs.ssh-tpm-agent.enable in
  # home.nix); gpg-agent has SSH support explicitly disabled there. ssh-tpm-agent
  # falls back to gpg's S.gpg-agent.ssh for non-TPM keys via its --fallback arg.
  SSH_AUTH_SOCK = "$XDG_RUNTIME_DIR/ssh-tpm-agent.sock";

  # Nix-built ncurses doesn't search distro paths by default, and home-manager's
  # generic-linux only wires TERMINFO_DIRS for systemd units, not interactive
  # shells. Set it here so Nix-built tools (less, etc.) find both Nix-installed
  # terminfo (e.g. ghostty) and the distro's.
  TERMINFO_DIRS = "${home}/.nix-profile/share/terminfo:/usr/share/terminfo";
}
// lib.optionalAttrs (!pkgs.stdenv.hostPlatform.isDarwin && isDesktop) {
  # Desktop-only: programs.firefox.enable is isDesktop-gated, so on a headless
  # host this would name a binary that isn't installed. Leave BROWSER unset
  # there and let each tool fall back to its own default rather than fail with
  # a bare command-not-found.
  BROWSER = "firefox";

  # GTK's file-chooser sidebar (and Nautilus, and anything else built on GIO)
  # enumerates drives through GVolumeMonitor. The only implementation that
  # knows about *unmounted* removable devices is gvfs's udisks2 monitor;
  # without it GIO falls back to GUnixVolumeMonitor, which reads just fstab and
  # /proc/mounts, so a USB stick that is plugged in but not yet mounted never
  # appears and there is nothing to click to mount it. wrapGAppsHook wraps this
  # var with `--prefix`, so each app's own dconf entry still lands ahead of
  # this one rather than being clobbered by it. Needs pkgs.gvfs on PATH too --
  # see the comment on it in home.nix for why a bare store path is not enough.
  GIO_EXTRA_MODULES = "${pkgs.gvfs}/lib/gio/modules";

          unbind = "Ctrl g";
        };
        locked = {
          "bind \"Alt s\"".SwitchToMode = "Normal";
          unbind = "Ctrl g";
        };
      };

      default_mode = "locked";
      pane_frames = false;
      show_startup_tips = false;
    };
  };
};

xdg = {
  mime.enable = !isDarwin;

  portal = {
    enable = !isDarwin && isDesktop;
    extraPortals = lib.optionals (!isDarwin && isDesktop) [
      (withHostNss pkgs.xdg-desktop-portal-gtk)
    ];
    xdgOpenUsePortal = !isDarwin && isDesktop;
    config = {
      common.default = [ "hyprland;gtk" ];
    };
  };

  mimeApps = {
    enable = !isDarwin && isDesktop;

    defaultApplications = {
      "text/html" = "firefox.desktop";
      "x-scheme-handler/http" = "firefox.desktop";
      "x-scheme-handler/https" = "firefox.desktop";
      "x-scheme-handler/mailto" = "thunderbird.desktop";
      "message/rfc822" = "thunderbird.desktop";
    };
  };

  dataHome = "${config.home.homeDirectory}/.local/share";
  configHome = "${config.home.homeDirectory}/.config";
  cacheHome = "${config.home.homeDirectory}/.cache";

  userDirs = {
    enable = true;

    desktop = "${config.home.homeDirectory}/desktop";
    documents = "${config.home.homeDirectory}/documents";
    download = "${config.home.homeDirectory}/downloads";
    music = "${config.home.homeDirectory}/drive/music";
    pictures = "${config.home.homeDirectory}/images";
  };

  configFile."newtab.html".text = newtabHtml;

  # Standalone home-manager doesn't put ~/.nix-profile/share/systemd/user in
  # systemd's search path, so the dbus-activated portal services fail with
  # "unknown unit" and ghostty's OpenURI portal call falls back to spawning
  # xdg-open (and the browser) as a child. Symlink the units in so dbus finds them.

